SELECT 
FROM t_pbccrc_report
WHERE customer_id_card = #{customerIdCard} AND customer_name = #{customerName}
ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT id FROM t_pbccrc_report
WHERE customer_name = #{customerName}
  AND customer_id_card = #{customerIdCard}
  AND create_time >= #{since}
ORDER BY create_time DESC
LIMIT 1
FOR UPDATE
